    "backup.groupGuides": "How to set up each destination",
    "backup.guidesAbout":
      "Every cloud here is yours, not ours: the backup goes to your account through your own setup, and nothing passes through anybody else.",
    "backup.guide.folderTitle": "A synced folder (Dropbox, Proton Drive, anything)",
    "backup.guide.folderStep1": "Install the sync client you already use and let it finish signing in.",
    "backup.guide.folderStep2":
      "Choose “A folder” above and pick a folder inside the one it syncs — a CodeFlow subfolder keeps it tidy.",
    "backup.guide.folderStep3":
      "That's all: the client uploads whatever lands there, so the backup travels on its own.",
    "backup.guide.icloudTitle": "iCloud Drive",
    "backup.guide.icloudMac1": "System Settings → your name → iCloud → turn on iCloud Drive.",
    "backup.guide.icloudMac2": "Choose “iCloud Drive” above; CodeFlow already knows where the folder is.",
    "backup.guide.icloudMac3":
      "On the other Mac, sign in to the same Apple Account and restore from the same folder.",
    "backup.guide.icloudWin1":
      "Install iCloud for Windows from the Microsoft Store and sign in with your Apple Account.",
    "backup.guide.icloudWin2":
      "Tick iCloud Drive in its window, so the iCloudDrive folder appears in File Explorer.",
    "backup.guide.icloudWin3":
      "Choose “iCloud Drive” above; the folder is found for you, on Windows and on Mac alike.",
    "backup.guide.icloudLinkWindows": "iCloud for Windows",
    "backup.guide.icloudNotFound":
      "No iCloud Drive folder found here. Follow the steps above, then reopen this panel.",
    "backup.guide.icloudNoLinux":
      "Apple ships no iCloud client for Linux — use a synced folder instead.",
    "backup.guide.icloudNoApi":
      "There is no “Connect iCloud” button because Apple publishes no API for third-party apps to reach iCloud Drive — the folder is the only way in, which is also why this needs no setup at all. If you would rather sign in to an account, OneDrive below does exactly that, on Windows and macOS alike.",

    "backup.guide.onedriveTitle": "OneDrive",
    "backup.guide.onedriveStep1":
      "Open Microsoft Entra ID → App registrations → New registration, and give it any name.",
    "backup.guide.onedriveStep2":
      "For supported account types, pick the one matching the account you'll back up to — personal, work or school, or both.",
    "backup.guide.onedriveStep3":
      "Add a platform → Mobile and desktop applications, with the redirect URI http://localhost — no port number, and not 127.0.0.1, which the portal rejects.",
    "backup.guide.onedriveStep4":
      "Copy the Application (client) ID into the field above, press Connect, and grant access in the browser.",
    "backup.guide.onedriveLinkRegister": "Register the application",
    "backup.guide.onedriveScope":
      "Access is limited to CodeFlow's own folder in your OneDrive — it cannot read anything else you keep there. No client secret is involved, and no OneDrive desktop client has to be installed.",
    "backup.guide.driveTitle": "Google Drive",
    "backup.guide.driveStep1": "Open the Google Cloud console and create a project (any name).",
    "backup.guide.driveStep2": "Enable the Google Drive API for it.",
    "backup.guide.driveStep3": "Under Credentials, create an OAuth client of type “Desktop app”.",
    "backup.guide.driveStep4": "Paste the client ID and client secret it gives you into the fields above.",
    "backup.guide.driveStep5": "Press Connect and grant access in the browser window that opens.",
