    "settings.githubTitle": "GitHub",
    "settings.githubHint":
      "Connect a GitHub account with a Personal Access Token (with `repo` scope) so CodeFlow can list and review pull requests. The token is stored in your OS keychain, never on disk in plain text.",
    "settings.githubHostLabel": "Host",
    "settings.githubHostHint": "Leave as github.com, or enter your GitHub Enterprise Server hostname (e.g. github.mycompany.com).",
    "settings.gitlabHint":
      "A GitLab personal access token with the `api` scope. Stored in your operating system's credential store, never in a file. One token per instance — gitlab.com and any self-managed GitLab can be connected at the same time.",
    "settings.gitlabHostLabel": "GitLab host",
    "settings.gitlabHostHint": "Leave as gitlab.com, or enter your self-managed GitLab hostname (e.g. git.mycompany.com).",
    "settings.jiraHint":
      "A Jira site plus the account e-mail and API token that go with it — Jira authenticates the pair, so the e-mail is required. Only the token reaches your OS keychain. Used to publish a backlog and to review an issue that already exists; Jira hosts no code, so nothing on the pull-request side offers it.",
