      "No se pudieron escribir {n} credencial(es) en el almacén del sistema. En macOS suele ser un aviso del llavero que se cerró — vuelve a restaurar para reintentarlo.",

    "backup.groupGuides": "Cómo configurar cada destino",
    "backup.guidesAbout":
      "Todas las nubes de aquí son tuyas, no nuestras: el respaldo llega a tu cuenta con tu propia configuración, sin pasar por nadie más.",
    "backup.guide.folderTitle": "Una carpeta sincronizada (Dropbox, Proton Drive, la que uses)",
    "backup.guide.folderStep1":
      "Instala el cliente de sincronización que ya usas y termina de iniciar sesión.",
    "backup.guide.folderStep2":
      "Elige “Una carpeta” arriba y apunta a una carpeta dentro de la que sincroniza — una subcarpeta CodeFlow lo deja ordenado.",
    "backup.guide.folderStep3":
      "Eso es todo: el cliente sube lo que caiga ahí, así que el respaldo viaja solo.",
    "backup.guide.icloudTitle": "iCloud Drive",
    "backup.guide.icloudMac1": "Ajustes del sistema → tu nombre → iCloud → activa iCloud Drive.",
    "backup.guide.icloudMac2": "Elige “iCloud Drive” arriba; CodeFlow ya sabe dónde está la carpeta.",
    "backup.guide.icloudMac3":
      "En el otro Mac, inicia sesión con la misma cuenta de Apple y restaura desde la misma carpeta.",
    "backup.guide.icloudWin1":
      "Instala iCloud para Windows desde la Microsoft Store e inicia sesión con tu cuenta de Apple.",
    "backup.guide.icloudWin2":
      "Marca iCloud Drive en su ventana, para que aparezca la carpeta iCloudDrive en el Explorador.",
    "backup.guide.icloudWin3":
      "Elige “iCloud Drive” arriba; la carpeta se detecta sola, tanto en Windows como en Mac.",
    "backup.guide.icloudLinkWindows": "iCloud para Windows",
    "backup.guide.icloudNotFound":
      "No se encontró la carpeta de iCloud Drive aquí. Sigue los pasos de arriba y vuelve a abrir este panel.",
    "backup.guide.icloudNoLinux":
      "Apple no publica cliente de iCloud para Linux — usa una carpeta sincronizada.",
    "backup.guide.icloudNoApi":
      "No hay botón de “Conectar iCloud” porque Apple no publica ninguna API para que apps de terceros lleguen a iCloud Drive — la carpeta es la única entrada, que es también por lo que esto no necesita configurar nada. Si prefieres iniciar sesión en una cuenta, OneDrive más abajo hace exactamente eso, igual en Windows que en macOS.",

    "backup.guide.onedriveTitle": "OneDrive",
    "backup.guide.onedriveStep1":
      "Abre Microsoft Entra ID → Registros de aplicaciones → Nuevo registro, y ponle cualquier nombre.",
    "backup.guide.onedriveStep2":
      "En los tipos de cuenta admitidos, elige el que corresponda a la cuenta donde vas a respaldar — personal, profesional o educativa, o ambas.",
    "backup.guide.onedriveStep3":
      "Agrega una plataforma → Aplicaciones móviles y de escritorio, con el URI de redirección http://localhost — sin número de puerto, y no 127.0.0.1, que el portal rechaza.",
    "backup.guide.onedriveStep4":
      "Copia el ID de aplicación (cliente) en el campo de arriba, pulsa Conectar y concede el acceso en el navegador.",
    "backup.guide.onedriveLinkRegister": "Registrar la aplicación",
    "backup.guide.onedriveScope":
      "El acceso se limita a la carpeta propia de CodeFlow dentro de tu OneDrive — no puede leer nada más de lo que guardes ahí. No interviene ningún secreto de cliente, y no hace falta tener instalado el cliente de escritorio de OneDrive.",
    "backup.guide.driveTitle": "Google Drive",
    "backup.guide.driveStep1": "Abre la consola de Google Cloud y crea un proyecto (con cualquier nombre).",
    "backup.guide.driveStep2": "Activa la API de Google Drive en ese proyecto.",
    "backup.guide.driveStep3": "En Credenciales, crea un cliente OAuth de tipo “Aplicación de escritorio”.",
    "backup.guide.driveStep4": "Pega el ID de cliente y el secreto que te da en los campos de arriba.",
    "backup.guide.driveStep5": "Pulsa Conectar y concede el acceso en la ventana del navegador que se abre.",
    "backup.guide.driveLinkEnable": "1. Activar la API de Drive",
    "backup.guide.driveLinkCreate": "2. Crear el cliente OAuth",
    "backup.guide.driveLinkDocs": "Cómo funciona",
    "backup.guide.driveScope":
      "El acceso se limita a los archivos que crea CodeFlow — no puede leer el resto de tu Drive.",
    "backup.guide.driveDesktopLink":
      "¿Prefieres no configurar nada? Instala Google Drive para escritorio y úsalo como carpeta.",


