    "settings.reviewStandardTitleForProject": "Estándar de revisión de PR — {name}",
    "settings.reviewStandardSelectWorkspace": "Selecciona un workspace para editar su estándar de revisión.",
    "settings.reviewStandardHint":
      "La metodología base con la que se revisa cada PR de este workspace (taxonomía estilo SonarQube, ratings A–E, Quality Gate, lentes de revisión y formato de salida). Es transversal — las reglas propias de un proyecto van en \"Contexto de revisión de PR\" / \"Instrucciones\", no aquí. Editarlo cambia cómo se califican y reportan las revisiones.",
    "settings.reviewStandardPlaceholder": "La metodología de revisión que la IA sigue para cada PR de este workspace…",
    "settings.reviewStandardResetConfirm": "¿Restaurar el estándar de revisión de este workspace al valor por defecto? Se perderán tus ediciones.",

    "settings.reviewHint":
      "Lo que Claude lee antes de revisar un pull request en este workspace: la metodología de revisión, el contexto que se le entrega y las memorias que ha guardado.",
    "settings.reviewTitleForProject": "Revisión de PR — {name}",
    "settings.reviewSelectWorkspace": "Selecciona un workspace para configurar su revisión de PR.",
    "settings.reviewTabStandard": "Estándar",
    "settings.reviewTabEngine": "Motor",
    "settings.engineHint":
      "Los números a los que realmente se somete una revisión. A diferencia de los prompts, esto lo aplica el código: el umbral decide qué hallazgos sobreviven, las severidades deciden qué se busca siquiera, y todo queda congelado en cada revisión guardada, para que una vieja siga diciendo bajo qué reglas se hizo.",
    "settings.engineLevel": "Nivel",
    "settings.engineMinConfidence": "Umbral de confianza",
